{
  "findings": [
    {
      "check_id": "CKV_AWS_24",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 22",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The security group 'vault' allows ingress from 0.0.0.0/0 to any port in var.ingress_ports, potentially including port 22."
    },
    {
      "check_id": "AVD-AWS-0124",
      "title": "Security group rule does not have a description",
      "resource": "aws_security_group.vault",
      "severity": "LOW",
      "explanation": "The ingress rules in the 'vault' security group lack descriptions, making it harder to understand their purpose."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      cidr_blocks = [\"0.0.0.0/0\"]\n      description = \"Allow inbound traffic on port ${port.value}\"\n    }\n  }\n}",
  "fix_summary": "Added descriptions to the ingress rules in the 'vault' security group. The original code remains otherwise unchanged."
}
